import{_ as t,o as e,c as u,ag as q}from"./chunks/framework.CAXxHpAX.js";const k=JSON.parse('{"title":"儒家金句","description":"","frontmatter":{},"headers":[],"relativePath":"40-原话金句/quote-儒家.md","filePath":"40-原话金句/quote-儒家.md","lastUpdated":1778155802000}'),r={name:"40-原话金句/quote-儒家.md"};function a(l,o,n,c,s,b){return e(),u("div",null,[...o[0]||(o[0]=[q('<h1 id="儒家金句" tabindex="-1">儒家金句 <a class="header-anchor" href="#儒家金句" aria-label="Permalink to &quot;儒家金句&quot;">​</a></h1><blockquote><p>了空居士关于处世、家庭、社会伦理的精彩原话集 含：家庭道场、待人处世、忍耐智慧、义利之辨、教育子女</p></blockquote><hr><h2 id="一、家庭道场" tabindex="-1">一、家庭道场 <a class="header-anchor" href="#一、家庭道场" aria-label="Permalink to &quot;一、家庭道场&quot;">​</a></h2><blockquote><p><strong>&quot;家庭是道场，工作单位是道场，社会是道场。怎么去对待家庭？怎么去对待社会？就在日常生活中。&quot;</strong> ——<a href="/60-原文段落/金刚经1分-修行在生活中">金刚经1分-修行在生活中</a></p></blockquote><blockquote><p><strong>&quot;家庭里面最重要还是我们男人。如果我们跟妻子在一起，她有什么不开心，你可以在旁边跟她说，拉拉手摇摇肩膀都可以。两个人都是硬邦邦的，永远是硬邦邦的。石头和石头之间不填上水泥浆，那个石头永远是摆不平的。&quot;</strong> ——修行入世（20090112b）</p></blockquote><blockquote><p><strong>&quot;一桩婚姻，自己觉得可以，长辈也许可。要有本事能赚钱，又要有些人情味，懂得关心体贴。如果具备这两种，这种人就可以托付终生。&quot;</strong> ——修行入世（20090112b）</p></blockquote><blockquote><p><strong>&quot;找对象，我们看别人马马虎虎，可能对方看我们也是马马虎虎。所以我老是提醒大家，那些马马虎虎的就是最恰当的。&quot;</strong> ——修行入世（20090112b）</p></blockquote><hr><h2 id="二、待人处世" tabindex="-1">二、待人处世 <a class="header-anchor" href="#二、待人处世" aria-label="Permalink to &quot;二、待人处世&quot;">​</a></h2><blockquote><p><strong>&quot;凡事尽力而为，做人问心无愧。&quot;</strong> ——答疑精选</p></blockquote><blockquote><p><strong>&quot;与人为善——在哪里都要这样。这是心能安静的基础。&quot;</strong> ——答疑精选</p></blockquote><blockquote><p><strong>&quot;冤亲平等——对伤害你的人和对帮助你的人，保持同样的心。不是麻木，是不被绑定。&quot;</strong> ——<a href="/60-原文段落/答疑2014-顺逆皆修与冤亲平等">答疑2014-顺逆皆修与冤亲平等</a></p></blockquote><blockquote><p><strong>&quot;整体观定善恶——不要只看眼前这一件事，把整个事情的前因后果都看清楚了，才知道这件事到底是好是坏。&quot;</strong> ——<a href="/60-原文段落/论坛-整体观定善恶">论坛-整体观定善恶</a></p></blockquote><blockquote><p><strong>&quot;别人对不起你，你原谅他，不是因为你懦弱，是因为你大气。&quot;</strong> ——答疑精选</p></blockquote><blockquote><p><strong>&quot;若真修道人，不见世间过——不是看不到别人的过错，而是看到别人的过错时，心里不因此起烦恼。&quot;</strong> ——处世系列</p></blockquote><hr><h2 id="三、忍耐与智慧" tabindex="-1">三、忍耐与智慧 <a class="header-anchor" href="#三、忍耐与智慧" aria-label="Permalink to &quot;三、忍耐与智慧&quot;">​</a></h2><blockquote><p><strong>&quot;忍耐不是懦夫，也不是胆怯，忍辱是智慧的做法。忍是留下余地，留下主动权。你要先忍住。不忍住，你门道都看不清，方法都不掌握。&quot;</strong> ——答疑专辑2019_佛学篇</p></blockquote><blockquote><p><strong>&quot;天地间有位才女李清照，她病重时对丈夫写&#39;莫对新人提旧妇&#39;，对儿子写&#39;须教继母作亲娘&#39;。&quot;</strong> ——修行入世（20090112b）</p></blockquote><blockquote><p><strong>&quot;看见人家丑恶的一面时，应该立刻检点自己。如果有这种缺点，要马上改正；如果没有，也要提醒自己，小心注意。&quot;</strong> ——蔡衍颛文集</p></blockquote><hr><h2 id="四、义利之辨" tabindex="-1">四、义利之辨 <a class="header-anchor" href="#四、义利之辨" aria-label="Permalink to &quot;四、义利之辨&quot;">​</a></h2><blockquote><p><strong>&quot;心胸不用宽广，也不用狭隘，最关键，就是以智慧去看待一切。该花一万我不会花九千，不该花的五元，我可能五元钱都不愿意花，我会看得很准的。&quot;</strong> ——答疑专辑2019_处世篇</p></blockquote><blockquote><p><strong>&quot;我们总结的经验就是用道理和良心和人家对论。评价一件事情都是用道理和良心，只要守住这两条，永远立于不败之地。&quot;</strong> ——修行入世（20090112b）</p></blockquote><blockquote><p><strong>&quot;什么叫做正，不偏不倚谓之正。自利利他的行为，损人利已或损已利人的都不是那么正。佛家讲&#39;无缘大慈，同体大悲&#39;，都是说我们个人的利益和集体利益放到一起。&quot;</strong> ——答疑专辑2014_佛道</p></blockquote><hr><h2 id="五、教育子女" tabindex="-1">五、教育子女 <a class="header-anchor" href="#五、教育子女" aria-label="Permalink to &quot;五、教育子女&quot;">​</a></h2><blockquote><p><strong>&quot;儿孙自有儿孙福，莫为儿孙做马牛。不是不管，是不要过度干涉。你把你的人生经验告诉他们，选择让他们自己做。&quot;</strong> ——处世系列</p></blockquote><blockquote><p><strong>&quot;因材施教——孔子对子路说&#39;要经长辈同意&#39;，对公西华说&#39;不用&#39;。同样的道理，不同的人要不同对待。&quot;</strong> ——<a href="/60-原文段落/金刚经7分-无为法而有差别">金刚经7分-无为法而有差别</a></p></blockquote><hr><h2 id="六、人生智慧" tabindex="-1">六、人生智慧 <a class="header-anchor" href="#六、人生智慧" aria-label="Permalink to &quot;六、人生智慧&quot;">​</a></h2><blockquote><p><strong>&quot;顺境不沉溺，逆境不气馁——保持平常心。&quot;</strong> ——答疑精选</p></blockquote><blockquote><p><strong>&quot;人生就是一场修行，你遇到的每一个人、每一件事，都是来度你的。&quot;</strong> ——答疑精选</p></blockquote><blockquote><p><strong>&quot;你把自己做好了，就是对这个世界最大的贡献。&quot;</strong> ——答疑精选</p></blockquote><blockquote><p><strong>&quot;司空见惯就是平常心。&quot;</strong> ——答疑精选</p></blockquote><hr><h2 id="简短金句" tabindex="-1">简短金句 <a class="header-anchor" href="#简短金句" aria-label="Permalink to &quot;简短金句&quot;">​</a></h2><blockquote><p>&quot;吃亏是福。&quot; &quot;一切随缘。&quot; &quot;别想太多。&quot; &quot;该放就放。&quot; &quot;活在当下。&quot; &quot;问心无愧。&quot;</p></blockquote><hr><blockquote><p>来源：处世系列（01-09）、答疑专辑2019处世篇、修行入世（20090112b）、蔡衍颛文集 整理日期：2026-05-07（新建儒家分类，从答疑/处世/修行入世原始文章中提炼）</p></blockquote>',41)])])}const h=t(r,[["render",a]]);export{k as __pageData,h as default};
